package components

import (
	"github.com/anthnel/devdesk/internal/forge"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Field indices used by CreationForm.
const (
	fieldType       = 0
	fieldName       = 1
	fieldDesc       = 2
	fieldVisibility = 3
	fieldTemplate   = 4
)

// allVisibilities is what every test in this file passes unless it is
// specifically exercising the narrowing itself — the caller's job
// (forge.Shape.VisibilitiesUnder), not this component's.
var allVisibilities = []string{"private", "internal", "public"}

func newGroupForm() *CreationForm {
	return NewCreationForm(0, "", "", "private", allVisibilities, forge.VocabularyFor(""))
}

func newProjectForm() *CreationForm {
	return NewCreationForm(1, "parent/group", "42", "private", allVisibilities, forge.VocabularyFor(""))
}

// feedForm applies messages in order.
func feedForm(f *CreationForm, msgs ...tea.Msg) *CreationForm {
	for _, m := range msgs {
		f, _ = f.Update(m)
	}
	return f

